cat > core/seat-units.spec.ts <<'EOF'
import { bookingTotal, toUnits, unitDescription, unitLabel } from './seat-units';
import { unitPrice } from './pricing';

describe('seat units', () => {
  it('groups row 15 identifiers into couches and keeps other seats single', () => {
    const units = toUnits(['R15C3', 'R15C4', 'R7C12', 'R15C1', 'R15C2']);
    expect(units.map((unit) => [unit.row, unit.start, unit.end, unit.couch])).toEqual([
      [7, 12, 12, false],
      [15, 1, 2, true],
      [15, 3, 4, true],
    ]);
  });

  it('describes couches as Couch a-b and seats by column', () => {
    const [seat, couch] = toUnits(['R15C3', 'R15C4', 'R3C12']).reverse();
    expect(unitDescription(seat)).toBe('12');
    expect(unitDescription(couch)).toBe('Couch 3-4');
    expect(unitLabel(couch)).toBe('3-4');
  });

  it('prices seats by row band and couches per couch', () => {
    const price = (ids: string[]) => toUnits(ids).map(unitPrice);
    expect(price(['R1C10', 'R5C1'])).toEqual([25, 25]);
    expect(price(['R6C1', 'R10C1'])).toEqual([32, 32]);
    expect(price(['R11C1', 'R14C24'])).toEqual([39, 39]);
    expect(price(['R15C1', 'R15C2'])).toEqual([89]);
    expect(bookingTotal(['R15C1', 'R15C2', 'R11C1'], unitPrice)).toBe(128);
  });
});
EOF
cat > checkout/checkout-validation.spec.ts <<'EOF'
import { CheckoutForm } from '../core/booking.service';
import { hasErrors, validateCheckout } from './checkout-validation';

const valid: CheckoutForm = {
  firstName: 'Anna',
  lastName: 'Kowalska',
  email: 'anna@example.com',
  confirmEmail: 'anna@example.com',
  phone: '',
  terms: true,
};

describe('validateCheckout', () => {
  it('accepts a complete form and an empty phone number', () => {
    expect(hasErrors(validateCheckout(valid))).toBe(false);
  });

  it('reports required fields and names', () => {
    const errors = validateCheckout({ ...valid, firstName: '', lastName: '', email: '', confirmEmail: '', terms: false });
    expect(errors).toEqual({
      firstName: 'First name is required',
      lastName: 'Last name is required',
      email: 'Email is required',
      confirmEmail: 'Confirm email is required',
      phone: undefined,
      terms: 'You must accept the terms and conditions',
    });
  });

  it('requires names of at least two characters', () => {
    expect(validateCheckout({ ...valid, firstName: 'A' }).firstName).toBe('First name must be at least 2 characters');
    expect(validateCheckout({ ...valid, lastName: 'B' }).lastName).toBe('Last name must be at least 2 characters');
  });

  it.each(['not-an-email', 'a@b', 'a@.com', 'a b@example.com', 'a@b.'])('rejects the email %s', (email) => {
    expect(validateCheckout({ ...valid, email, confirmEmail: email }).email).toBe('Enter a valid email address');
  });

  it('compares the confirmation with the email as typed', () => {
    expect(validateCheckout({ ...valid, confirmEmail: 'anna@example.com ' }).confirmEmail).toBe(
      'Email addresses do not match',
    );
  });

  it('accepts exactly nine digits as a phone number and nothing else', () => {
    expect(validateCheckout({ ...valid, phone: '123456789' }).phone).toBeUndefined();
    expect(validateCheckout({ ...valid, phone: '12345678' }).phone).toBe('Phone number must be exactly 9 digits');
    expect(validateCheckout({ ...valid, phone: '1234567890' }).phone).toBe('Phone number must be exactly 9 digits');
    expect(validateCheckout({ ...valid, phone: '12345678a' }).phone).toBe('Phone number must be exactly 9 digits');
  });
});
EOF
cat > core/dates.spec.ts <<'EOF'
import { parseIsoDate, showDate, toIsoDate } from './dates';

describe('dates', () => {
  it('parses only real ISO dates', () => {
    expect(parseIsoDate('2026-09-15')).not.toBeNull();
    expect(parseIsoDate('2026-02-30')).toBeNull();
    expect(parseIsoDate('15-09-2026')).toBeNull();
    expect(parseIsoDate(null)).toBeNull();
  });

  it('formats the show date as weekday, day without zero, three-letter month and time', () => {
    expect(showDate('2026-09-15', '16:00')).toBe('Tuesday 15 Sep 16:00');
    expect(showDate('2026-09-05', '19:30')).toBe('Saturday 5 Sep 19:30');
  });

  it('round-trips ISO dates', () => {
    expect(toIsoDate(parseIsoDate('2026-01-09')!)).toBe('2026-01-09');
  });
});
EOF
