      expect(text('email-error')).toBe('Email is required');
      expect(document.querySelectorAll('[data-testid="phone-error"]')).toHaveLength(0);

      one('pay-button').click();
      settle();
      expect(text('last-name-error')).toBe('Last name is required');
      expect(text('terms-error')).toBe('You must accept the terms and conditions');
      expect(toastText()).toBe('The form contains errors');
      http.expectNone(`${API}/reservations`);
    });

    it('posts the reservation, opens the confirmation and clears the booking on continue', async () => {
      await openCheckout();
      input('first-name-input', 'Anna');
      input('last-name-input', 'Kowalska');
      input('email-input', 'anna.kowalska@example.com');
      input('confirm-email-input', 'anna.kowalska@example.com');
      input('phone-input', '123456789');
      one('terms-checkbox').querySelector('input')?.click();
      settle();

      one('pay-button').click();
      const request = http.expectOne(`${API}/reservations`);
      expect(request.request.body).toEqual({
        screeningId: 1,
        seats: ['R7C12', 'R15C1', 'R15C2'],
        customer: {
          firstName: 'Anna',
          lastName: 'Kowalska',
          email: 'anna.kowalska@example.com',
          phone: '123456789',
        },
        totalPrice: 121,
      });
      request.flush({ id: 1, ...request.request.body }, { status: 201, statusText: 'Created' });
      await fixture.whenStable();
      settle();

      expect(router.url).toBe('/confirmation');
      expect(text('confirmation-heading')).toBe('Payment successful');
      expect(text('confirmation-message')).toBe('Your tickets will be sent shortly to anna.kowalska@example.com');

      one('confirmation-continue-button').click();
      await fixture.whenStable();
      expect(router.url).toBe('/');
      expect(sessionStorage.getItem('cinescope.booking')).toBeNull();
    });

    it('keeps the form and shows a toast when the payment fails', async () => {
      await openCheckout();
      input('first-name-input', 'Anna');
      input('last-name-input', 'Kowalska');
      input('email-input', 'anna@example.com');
      input('confirm-email-input', 'anna@example.com');
      one('terms-checkbox').querySelector('input')?.click();
      settle();

      one('pay-button').click();
      http.expectOne(`${API}/reservations`).flush('nope', { status: 500, statusText: 'Server Error' });
      settle();

      expect(router.url).toBe('/screenings/1/checkout');
      expect((one('first-name-input') as HTMLInputElement).value).toBe('Anna');
      expect(text('pay-button')).toBe('Pay 121.00 PLN');
      expect(toastText()).toBe('Payment failed. Please try again.');
    });
  });

  describe('booking guards', () => {
    it('redirects the summary and checkout to the movie list without a booking', async () => {
      await navigate('/screenings/1/summary');
      expect(router.url).toBe('/');
      await navigate('/screenings/1/checkout');
      expect(router.url).toBe('/');
      await navigate('/confirmation');
      expect(router.url).toBe('/');
    });

    it('redirects unknown URLs to the movie list', async () => {
      await navigate('/nothing/here');
      expect(router.url).toBe('/');
    });
  });
});

import { bookingTotal, toUnits, unitDescription, unitLabel } from './seat-units';
import { unitPrice } from './pricing';

describe('seat units', () => {
  it('groups row 15 identifiers into couches and keeps other seats single', () => {
    const units = toUnits(['R15C3', 'R15C4', 'R7C12', 'R15C1', 'R15C2']);
    expect(units.map((unit) => [unit.row, unit.start, unit.end, unit.couch])).toEqual([
      [7, 12, 12, false],
      [15, 1, 2, true],
      [15, 3, 4, true],
    ]);
  });

  it('describes couches as Couch a-b and seats by column', () => {
    const [seat, couch] = toUnits(['R15C3', 'R15C4', 'R3C12']);
    expect(unitDescription(seat)).toBe('12');
    expect(unitDescription(couch)).toBe('Couch 3-4');
    expect(unitLabel(couch)).toBe('3-4');
  });

  it('prices seats by row band and couches per couch', () => {
    const price = (ids: string[]) => toUnits(ids).map(unitPrice);
    expect(price(['R1C10', 'R5C1'])).toEqual([25, 25]);
    expect(price(['R6C1', 'R10C1'])).toEqual([32, 32]);
    expect(price(['R11C1', 'R14C24'])).toEqual([39, 39]);
    expect(price(['R15C1', 'R15C2'])).toEqual([89]);
    expect(bookingTotal(['R15C1', 'R15C2', 'R11C1'], unitPrice)).toBe(128);
  });
});

import { buildAuditorium, CouchItem, LayoutItem, SeatItem } from './auditorium';

const none = new Set<string>();

function seatsOf(items: LayoutItem[]): SeatItem[] {
  return items.filter((item): item is SeatItem => item.kind === 'seat');
}

function couchesOf(items: LayoutItem[]): CouchItem[] {
  return items.filter((item): item is CouchItem => item.kind === 'couch');
}

function kindsOf(items: LayoutItem[]): string[] {
  return items.map((item) => item.kind);
}

describe('buildAuditorium', () => {
  const rows = buildAuditorium(none, none);

  it('has 15 rows numbered 1 to 15', () => {
    expect(rows.map((row) => row.number)).toEqual(Array.from({ length: 15 }, (_, i) => i + 1));
  });

  it('has 308 selectable elements: 200 seats in rows 1-10, 96 in rows 11-14 and 12 couches in row 15', () => {
    const selectable = (row: number) => rows[row - 1].items.filter((i) => i.kind === 'seat' || i.kind === 'couch');
    const count = (from: number, to: number) =>
      Array.from({ length: to - from + 1 }, (_, i) => selectable(from + i).length).reduce((a, b) => a + b, 0);
    expect(count(1, 10)).toBe(200);
    expect(count(11, 14)).toBe(96);
    expect(count(15, 15)).toBe(12);
  });

  it('numbers columns globally, starting at 5 in rows 1-10 and at 1 in rows 11-14', () => {
    const columnsOf = (row: number) => seatsOf(rows[row - 1].items).map((seat) => seat.column);
    expect(columnsOf(1)[0]).toBe(5);
    expect(columnsOf(1).at(-1)).toBe(24);
    expect(columnsOf(11)[0]).toBe(1);
    expect(columnsOf(11).at(-1)).toBe(24);
  });

  it('places both aisles in every row, between columns 4 and 5 and between columns 20 and 21', () => {
    const row11 = kindsOf(rows[10].items);
    expect(row11.indexOf('aisle')).toBe(4);
    expect(row11.lastIndexOf('aisle')).toBe(21);
    const row1 = kindsOf(rows[0].items);
    expect(row1.indexOf('aisle')).toBe(1);
    expect(row1.lastIndexOf('aisle')).toBe(18);
    for (const row of rows) {
      expect(row.items.filter((item) => item.kind === 'aisle')).toHaveLength(2);
    }
  });

  it('leaves an empty entrance before column 5 in rows 1-10 only', () => {
    expect(rows[0].items[0].kind).toBe('entrance');
    expect(rows[9].items[0].kind).toBe('entrance');
    expect(rows[10].items[0].kind).toBe('seat');
  });

  it('marks six accessible seats in row 1, columns 10 to 15', () => {
    const accessible = seatsOf(rows[0].items).filter((seat) => seat.state === 'accessible');
    expect(accessible.map((seat) => seat.column)).toEqual([10, 11, 12, 13, 14, 15]);
  });

  it('renders 12 couches in row 15 covering columns 1-2 through 23-24', () => {
    const couches = couchesOf(rows[14].items);
    expect(couches.map((couch) => [couch.start, couch.end])).toEqual(
      Array.from({ length: 12 }, (_, i) => [i * 2 + 1, i * 2 + 2]),
    );
    expect(seatsOf(rows[14].items)).toHaveLength(0);
  });

  it('marks a couch unavailable when either of its seats is occupied', () => {
    const occupied = buildAuditorium(new Set(['R15C6']), none);
    expect(couchesOf(occupied[14].items).find((couch) => couch.start === 5)?.state).toBe('unavailable');
    expect(couchesOf(occupied[14].items).find((couch) => couch.start === 1)?.state).toBe('available');
  });

  it('reports selected accessible seats as selected and occupied accessible seats as unavailable', () => {
    const stateOf = (occupied: string[], selected: string[], column: number) =>
      seatsOf(buildAuditorium(new Set(occupied), new Set(selected))[0].items).find((s) => s.column === column)?.state;
    expect(stateOf([], ['R1C10'], 10)).toBe('selected');
    expect(stateOf(['R1C11'], [], 11)).toBe('unavailable');
    expect(stateOf([], [], 12)).toBe('accessible');
    expect(stateOf([], [], 16)).toBe('available');
  });
});

import { Component, computed, inject, signal } from '@angular/core';
import { takeUntilDestroyed } from '@angular/core/rxjs-interop';
import { ActivatedRoute, Router } from '@angular/router';
import { MatButtonModule } from '@angular/material/button';
import { MatDatepickerModule } from '@angular/material/datepicker';
import { MatFormFieldModule } from '@angular/material/form-field';
import { MatInputModule } from '@angular/material/input';
import { forkJoin, Subscription } from 'rxjs';
import { ApiService } from '../core/api.service';
import { addDays, parseIsoDate, startOfToday, toIsoDate, weekdayName } from '../core/dates';
import { Movie, Screening } from '../core/models';

type LoadState = 'loading' | 'error' | 'loaded';

const today = startOfToday();

@Component({
  selector: 'app-movie-list',
  imports: [MatButtonModule, MatDatepickerModule, MatFormFieldModule, MatInputModule],
  templateUrl: './movie-list.component.html',
  styleUrl: './movie-list.component.scss',
})
export class MovieListComponent {
  private readonly api = inject(ApiService);
  private readonly router = inject(Router);
  private readonly route = inject(ActivatedRoute);

  readonly minDate = today;
  readonly dayButtons = [0, 1, 2, 3, 4].map((offset) => {
    const date = addDays(today, offset);
    return { iso: toIsoDate(date), label: offset === 0 ? 'Today' : weekdayName(date) };
  });

  readonly selectedIso = signal(toIsoDate(today));
  readonly state = signal<LoadState>('loading');
  private readonly movies = signal<Movie[]>([]);
  private readonly screenings = signal<Screening[]>([]);
  private request?: Subscription;

  readonly pickerDate = computed(() => {
    const iso = this.selectedIso();
    return this.dayButtons.some((day) => day.iso === iso) ? null : parseIsoDate(iso);
  });

  readonly cards = computed(() => {
    const screenings = this.screenings();
    return this.movies()
      .map((movie) => ({
        movie,
        screenings: screenings
          .filter((screening) => screening.movieId === movie.id)
          .sort((a, b) => a.time.localeCompare(b.time)),
      }))
      .filter((card) => card.screenings.length > 0);
  });

  constructor() {
    this.route.queryParamMap.pipe(takeUntilDestroyed()).subscribe((params) => {
      const requested = parseIsoDate(params.get('date'));
      const day = requested && requested >= today ? requested : today;
      this.selectedIso.set(toIsoDate(day));
      this.load();
    });
  }

  isSelected(iso: string): boolean {
    return this.selectedIso() === iso;
  }

  selectDay(iso: string): void {
    this.router.navigate([], { queryParams: { date: iso } });
  }

  pickDate(date: Date | null): void {
    if (date) {
      this.selectDay(toIsoDate(date));
    }
  }

  openScreening(id: number): void {
    this.router.navigate(['/screenings', id, 'seats']);
  }

  retry(): void {
    this.load();
  }

  private load(): void {
    this.request?.unsubscribe();
    this.state.set('loading');
    this.request = forkJoin({
      movies: this.api.movies(),
      screenings: this.api.screeningsOn(this.selectedIso()),
    }).subscribe({
      next: ({ movies, screenings }) => {
        this.movies.set(movies);
        this.screenings.set(screenings);
        this.state.set('loaded');
      },
      error: () => this.state.set('error'),
    });
  }
}

